import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"examples/index.md","filePath":"examples/index.md","lastUpdated":null}'),c={name:"examples/index.md"};function i(r,e,s,n,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><p>Every example checks with <code>linnet lint --std stdlib examples/&lt;name&gt;</code>, formats cleanly, materializes in PyTorch and JAX, and exports to StableHLO; the tests under <code>python/linnet/tests/torch</code> compare the model examples against hand-written PyTorch references.</p><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th></tr></thead><tbody><tr><td><code>01-linear</code></td><td>A generic <code>op</code> in index notation and the block that owns its weights.</td></tr><tr><td><code>02-attention</code></td><td>Softmax and attention written as comprehensions with shape packs.</td></tr><tr><td><code>03-block-and-weights</code></td><td>A block hierarchy, sub arrays, <code>static for</code>, and the parameter manifest.</td></tr><tr><td><code>04-tiny-transformer</code></td><td>A package built only from the standard library, with rotary tables as inputs.</td></tr><tr><td><code>05-llama</code></td><td>A Llama-style decoder as a multi-module package: <code>crate.</code> imports, a <code>pub const</code> base frequency, rotary tables computed at compile time from <code>iota</code>, grouped-query attention whose <code>where</code> clause states the divisibility the reshapes rely on, <code>broadcast_to</code> for repeating key/value heads, six entries (<code>forward</code>; <code>next_token</code>, which slices the last position with <code>S - 1</code>; <code>decode</code>, which generates one token at a time from per-layer KV caches held in <code>state</code> members and written with a masked <code>select</code> at the runtime position; <code>generate&lt;Steps&gt;</code>, greedy decoding inside the graph with <code>static for i in 0..Steps</code> and <code>std.nn.decoding::argmax</code>; <code>sample&lt;Steps&gt;</code>, keyed sampling with <code>std.random</code>; and <code>generate_until&lt;MaxNew&gt;</code>, a runtime <code>while</code> loop that stops once every row has produced the end token), and a dtype generic defaulting to <code>bf16</code>.</td></tr><tr><td><code>06-gpt2</code></td><td>GPT-2: learned positions looked up with <code>embedding(iota&lt;i32&gt;(S), wpe)</code> under <code>where S &lt;= MaxPositions</code>, LayerNorm with a bias passed as an optional, a fused QKV projection split by slicing with dimension arithmetic (<code>H:2 * H</code>), the tanh GELU, and an output head tied to the token embedding through a contraction.</td></tr><tr><td><code>07-vit</code></td><td>A Vision Transformer: patches cut with <code>reshape</code> and <code>permute</code> whose element counts the checker proves from <code>Height % Patch == 0</code>, a class token concatenated after <code>broadcast_to</code>, a position table sized by <code>(Height / Patch) * (Width / Patch) + 1</code>, unmasked attention (<code>none</code>), and a pooling strategy chosen by matching a compile-time <code>enum</code> constant.</td></tr><tr><td><code>08-clip</code></td><td>A CLIP-style dual encoder as a package whose towers are separate modules sharing one encoder module: the vision tower runs it without a mask (<code>none</code>), the text tower with <code>some(causal_mask(...))</code>, and the root block exposes three entries over the same parameters — <code>embed_image</code>, <code>embed_text</code>, and <code>similarity</code>, an L2-normalized contraction scaled by a learned temperature stored as a <code>Tensor[1; f32]</code>.</td></tr></tbody></table><p>Weights bind by parameter path (<code>linnet inspect --parameters</code>); the models have no implicit initialization, so the tests fill them with random tensors through SafeTensors.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>Each example&#39;s complete source, highlighted:</p><ul><li><a href="/examples/01-linear">01-linear</a></li><li><a href="/examples/02-attention">02-attention</a></li><li><a href="/examples/03-block-and-weights">03-block-and-weights</a></li><li><a href="/examples/04-tiny-transformer">04-tiny-transformer</a></li><li><a href="/examples/05-llama">05-llama</a></li><li><a href="/examples/06-gpt2">06-gpt2</a></li><li><a href="/examples/07-vit">07-vit</a></li><li><a href="/examples/08-clip">08-clip</a></li></ul>',7)])])}const u=t(c,[["render",i]]);export{m as __pageData,u as default};
